class ATM {
    private static final int[] VALUES = new int[] {20, 50, 100, 200, 500};
    private final long[] stock = new long[5];

    public ATM() {
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < VALUES.length; i++) {
            stock[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] plan = new int[VALUES.length];
        long remaining = amount;
        for (int i = VALUES.length - 1; i >= 0; i--) {
            long take = Math.min(stock[i], remaining / VALUES[i]);
            plan[i] = (int) take;
            remaining -= take * VALUES[i];
        }
        if (remaining != 0) {
            return new int[] {-1};
        }
        for (int i = 0; i < VALUES.length; i++) {
            stock[i] -= plan[i];
        }
        return plan;
    }
}

class ATM {
    private static final int[] VALUES = new int[] {20, 50, 100, 200, 500};
    private long[] inventory = new long[5];

    public ATM() {
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < VALUES.length; i++) {
            inventory[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        long[] trial = inventory.clone();
        int[] result = new int[VALUES.length];
        long remaining = amount;
        for (int i = VALUES.length - 1; i >= 0; i--) {
            long take = Math.min(trial[i], remaining / VALUES[i]);
            result[i] = (int) take;
            trial[i] -= take;
            remaining -= take * VALUES[i];
        }
        if (remaining != 0) {
            return new int[] {-1};
        }
        inventory = trial;
        return result;
    }
}

