class ATM {
    private static final int[] VALUES = new int[] {20, 50, 100, 200, 500};
    private final long[] notes = new long[5];

    public ATM() {
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < VALUES.length; i++) {
            notes[i] += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] plan = new int[VALUES.length];
        if (!fillPlan(VALUES.length - 1, amount, plan)) {
            return new int[] {-1};
        }
        for (int i = 0; i < VALUES.length; i++) {
            notes[i] -= plan[i];
        }
        return plan;
    }

    private boolean fillPlan(int index, long remaining, int[] plan) {
        if (remaining == 0) {
            return true;
        }
        if (index < 0) {
            return false;
        }
        long take = Math.min(notes[index], remaining / VALUES[index]);
        plan[index] = (int) take;
        return fillPlan(index - 1, remaining - take * VALUES[index], plan);
    }
}

class ATM {
    private static class Cassette {
        final int value;
        long count;

        Cassette(int value) {
            this.value = value;
        }
    }

    private final Cassette[] cassettes = new Cassette[] {
            new Cassette(20), new Cassette(50), new Cassette(100), new Cassette(200), new Cassette(500)
    };

    public ATM() {
    }

    public void deposit(int[] banknotesCount) {
        for (int i = 0; i < cassettes.length; i++) {
            cassettes[i].count += banknotesCount[i];
        }
    }

    public int[] withdraw(int amount) {
        int[] result = new int[cassettes.length];
        long remaining = amount;
        for (int i = cassettes.length - 1; i >= 0; i--) {
            Cassette cassette = cassettes[i];
            long take = Math.min(cassette.count, remaining / cassette.value);
            result[i] = (int) take;
            remaining -= take * cassette.value;
        }
        if (remaining != 0) {
            return new int[] {-1};
        }
        for (int i = 0; i < cassettes.length; i++) {
            cassettes[i].count -= result[i];
        }
        return result;
    }
}
